#pragma warning disable CA1725
using FluentValidation;
using MediatR;
using WhatsBiz.Application.Common.Exceptions;
using WhatsBiz.Application.Common.Interfaces;
using WhatsBiz.Domain.Warehouses;
namespace WhatsBiz.Application.Features.Warehouses;
public sealed record AddressDto(Guid? AddressId, string AddressLine1, string? AddressLine2, string City, string? District, string State, string Country, string PostalCode); public sealed record ContactDto(Guid? ContactId, string ContactPerson, string? Designation, string? Mobile, string? Email, bool IsPrimary); public sealed record BinDto(Guid? BinId, string BinCode, string BinName, decimal MaximumCapacity, bool IsActive); public sealed record ZoneDto(Guid? ZoneId, string ZoneCode, string ZoneName, string? Description, bool IsActive, IReadOnlyCollection<BinDto> Bins); public sealed record WarehouseInput(string WarehouseCode, string WarehouseName, Guid WarehouseTypeId, Guid? BranchId, string? ManagerName, string? Email, string? Phone, string? Mobile, decimal Capacity, bool IsDefault, bool IsActive, string? Remarks, AddressDto? Address, IReadOnlyCollection<ContactDto> Contacts, IReadOnlyCollection<ZoneDto> Zones); public sealed record WarehouseDto(Guid WarehouseId, string WarehouseCode, string WarehouseName, Guid WarehouseTypeId, string TypeName, Guid? BranchId, string? ManagerName, string? Email, string? Phone, string? Mobile, decimal Capacity, Guid? AddressId, bool IsDefault, bool IsActive, string? Remarks, AddressDto? Address, IReadOnlyCollection<ContactDto> Contacts, IReadOnlyCollection<ZoneDto> Zones); public sealed record WarehouseListDto(Guid WarehouseId, string WarehouseCode, string WarehouseName, Guid WarehouseTypeId, string TypeName, string? ManagerName, string? Mobile, decimal Capacity, bool IsDefault, bool IsActive); public sealed record PagedWarehouses(IReadOnlyCollection<WarehouseListDto> Items, int TotalCount, int PageNumber, int PageSize); public sealed record WarehouseDropdownDto(Guid WarehouseId, string WarehouseCode, string WarehouseName); public sealed record WarehouseTypeDto(Guid WarehouseTypeId, string TypeCode, string TypeName, string? Description, bool IsActive); public sealed record WarehouseTypeInput(string TypeCode, string TypeName, string? Description, bool IsActive); public sealed record ImportResult(int ImportedCount, IReadOnlyCollection<string> Errors);
public sealed record GetWarehouses(string? Search, bool? IsActive, Guid? WarehouseTypeId, string SortBy, bool Descending, int PageNumber, int PageSize) : IRequest<PagedWarehouses>; public sealed record GetWarehouse(Guid Id) : IRequest<WarehouseDto>; public sealed record CreateWarehouse(WarehouseInput Input) : IRequest<WarehouseDto>; public sealed record UpdateWarehouse(Guid Id, WarehouseInput Input) : IRequest<WarehouseDto>; public sealed record DeleteWarehouse(Guid Id) : IRequest; public sealed record WarehouseDropdown(string? Search) : IRequest<IReadOnlyCollection<WarehouseDropdownDto>>; public sealed record GetWarehouseTypes : IRequest<IReadOnlyCollection<WarehouseTypeDto>>; public sealed record CreateWarehouseType(WarehouseTypeInput Input) : IRequest<WarehouseTypeDto>; public sealed record UpdateWarehouseType(Guid Id, WarehouseTypeInput Input) : IRequest<WarehouseTypeDto>; public sealed record DeleteWarehouseType(Guid Id) : IRequest; public sealed record ExportWarehouses : IRequest<byte[]>; public sealed record WarehouseTemplate : IRequest<byte[]>; public sealed record ImportWarehouses(byte[] Data) : IRequest<ImportResult>;
public sealed class WarehouseInputValidator : AbstractValidator<WarehouseInput> { public WarehouseInputValidator() { RuleFor(x => x.WarehouseCode).NotEmpty().MaximumLength(50); RuleFor(x => x.WarehouseName).NotEmpty().MaximumLength(200); RuleFor(x => x.WarehouseTypeId).NotEmpty(); RuleFor(x => x.Email).EmailAddress().When(x => !string.IsNullOrWhiteSpace(x.Email)); RuleFor(x => x.Phone).Matches("^[0-9+() -]{7,20}$").When(x => !string.IsNullOrWhiteSpace(x.Phone)); RuleFor(x => x.Mobile).Matches("^[0-9+() -]{7,15}$").When(x => !string.IsNullOrWhiteSpace(x.Mobile)); RuleFor(x => x.Capacity).GreaterThanOrEqualTo(0); RuleForEach(x => x.Contacts).ChildRules(c => c.RuleFor(x => x.Email).EmailAddress().When(x => !string.IsNullOrWhiteSpace(x.Email))); RuleForEach(x => x.Zones).ChildRules(z => { z.RuleFor(x => x.ZoneCode).NotEmpty(); z.RuleFor(x => x.ZoneName).NotEmpty(); }); } }
public sealed class CreateWarehouseValidator : AbstractValidator<CreateWarehouse> { public CreateWarehouseValidator() => RuleFor(x => x.Input).SetValidator(new WarehouseInputValidator()); }
public sealed class UpdateWarehouseValidator : AbstractValidator<UpdateWarehouse> { public UpdateWarehouseValidator() => RuleFor(x => x.Input).SetValidator(new WarehouseInputValidator()); }
public sealed class WarehouseTypeInputValidator : AbstractValidator<WarehouseTypeInput> { public WarehouseTypeInputValidator() { RuleFor(x => x.TypeCode).NotEmpty().MaximumLength(30); RuleFor(x => x.TypeName).NotEmpty().MaximumLength(100); } }
internal static class WarehouseMap { public static WarehouseDto D(Warehouse w) => new(w.WarehouseId, w.WarehouseCode, w.WarehouseName, w.WarehouseTypeId, w.WarehouseType?.TypeName ?? "", w.BranchId, w.ManagerName, w.Email, w.Phone, w.Mobile, w.Capacity, w.AddressId, w.IsDefault, w.IsActive, w.Remarks, w.Address is null ? null : new(w.Address.AddressId, w.Address.AddressLine1, w.Address.AddressLine2, w.Address.City, w.Address.District, w.Address.State, w.Address.Country, w.Address.PostalCode), w.Contacts.Select(x => new ContactDto(x.ContactId, x.ContactPerson, x.Designation, x.Mobile, x.Email, x.IsPrimary)).ToArray(), w.Zones.Select(z => new ZoneDto(z.ZoneId, z.ZoneCode, z.ZoneName, z.Description, z.IsActive, z.Bins.Select(b => new BinDto(b.BinId, b.BinCode, b.BinName, b.MaximumCapacity, b.IsActive)).ToArray())).ToArray()); public static void Apply(Warehouse w, WarehouseInput i) { w.WarehouseCode = i.WarehouseCode.Trim().ToUpperInvariant(); w.WarehouseName = i.WarehouseName.Trim(); w.WarehouseTypeId = i.WarehouseTypeId; w.BranchId = i.BranchId; w.ManagerName = i.ManagerName; w.Email = i.Email; w.Phone = i.Phone; w.Mobile = i.Mobile; w.Capacity = i.Capacity; w.IsDefault = i.IsDefault; w.IsActive = i.IsActive; w.Remarks = i.Remarks; if (i.Address is not null) { w.Address = new WarehouseAddress { AddressId = i.Address.AddressId ?? Guid.NewGuid(), WarehouseId = w.WarehouseId, AddressLine1 = i.Address.AddressLine1, AddressLine2 = i.Address.AddressLine2, City = i.Address.City, District = i.Address.District, State = i.Address.State, Country = i.Address.Country, PostalCode = i.Address.PostalCode }; } w.Contacts = i.Contacts.Select(x => new WarehouseContact { ContactId = x.ContactId ?? Guid.NewGuid(), WarehouseId = w.WarehouseId, ContactPerson = x.ContactPerson, Designation = x.Designation, Mobile = x.Mobile, Email = x.Email, IsPrimary = x.IsPrimary }).ToList(); w.Zones = i.Zones.Select(z => { var zone = new WarehouseZone { ZoneId = z.ZoneId ?? Guid.NewGuid(), WarehouseId = w.WarehouseId, ZoneCode = z.ZoneCode.Trim().ToUpperInvariant(), ZoneName = z.ZoneName, Description = z.Description, IsActive = z.IsActive }; zone.Bins = z.Bins.Select(b => new WarehouseBin { BinId = b.BinId ?? Guid.NewGuid(), WarehouseId = w.WarehouseId, ZoneId = zone.ZoneId, BinCode = b.BinCode.Trim().ToUpperInvariant(), BinName = b.BinName, MaximumCapacity = b.MaximumCapacity, IsActive = b.IsActive }).ToList(); return zone; }).ToList(); } }
public sealed class WarehouseHandlers(IWarehouseRepository repository, IWarehouseSpreadsheetService spreadsheet, ICurrentUserService user) : IRequestHandler<GetWarehouses, PagedWarehouses>, IRequestHandler<GetWarehouse, WarehouseDto>, IRequestHandler<CreateWarehouse, WarehouseDto>, IRequestHandler<UpdateWarehouse, WarehouseDto>, IRequestHandler<DeleteWarehouse>, IRequestHandler<WarehouseDropdown, IReadOnlyCollection<WarehouseDropdownDto>>, IRequestHandler<GetWarehouseTypes, IReadOnlyCollection<WarehouseTypeDto>>, IRequestHandler<CreateWarehouseType, WarehouseTypeDto>, IRequestHandler<UpdateWarehouseType, WarehouseTypeDto>, IRequestHandler<DeleteWarehouseType>, IRequestHandler<ExportWarehouses, byte[]>, IRequestHandler<WarehouseTemplate, byte[]>, IRequestHandler<ImportWarehouses, ImportResult> { public async Task<PagedWarehouses> Handle(GetWarehouses q, CancellationToken t) { var (x, n) = await repository.Search(q.Search, q.IsActive, q.WarehouseTypeId, q.SortBy, q.Descending, q.PageNumber, q.PageSize, t); return new(x.Select(w => new WarehouseListDto(w.WarehouseId, w.WarehouseCode, w.WarehouseName, w.WarehouseTypeId, w.WarehouseType?.TypeName ?? "", w.ManagerName, w.Mobile, w.Capacity, w.IsDefault, w.IsActive)).ToArray(), n, q.PageNumber, q.PageSize); } public async Task<WarehouseDto> Handle(GetWarehouse q, CancellationToken t) => WarehouseMap.D(await repository.GetById(q.Id, false, t) ?? throw new EntityNotFoundException("Warehouse not found.")); public async Task<WarehouseDto> Handle(CreateWarehouse q, CancellationToken t) { if (await repository.Duplicate(q.Input.WarehouseCode, q.Input.WarehouseName, null, t)) throw new BusinessRuleException("Duplicate warehouse code or name."); var w = new Warehouse { CreatedBy = user.Username }; WarehouseMap.Apply(w, q.Input); w.AddressId = null; repository.Add(w); await repository.Save(t); if (w.Address is not null) { w.AddressId = w.Address.AddressId; await repository.Save(t); } return WarehouseMap.D(await repository.GetById(w.WarehouseId, false, t) ?? w); } public async Task<WarehouseDto> Handle(UpdateWarehouse q, CancellationToken t) { var w = await repository.GetById(q.Id, true, t) ?? throw new EntityNotFoundException("Warehouse not found."); if (await repository.Duplicate(q.Input.WarehouseCode, q.Input.WarehouseName, q.Id, t)) throw new BusinessRuleException("Duplicate warehouse code or name."); w.AddressId = null; await repository.Save(t); repository.RemoveChildren(w); await repository.Save(t); WarehouseMap.Apply(w, q.Input); w.AddressId = null; w.ModifiedOn = DateTimeOffset.UtcNow; w.ModifiedBy = user.Username; await repository.Save(t); if (w.Address is not null) { w.AddressId = w.Address.AddressId; await repository.Save(t); } return WarehouseMap.D(await repository.GetById(w.WarehouseId, false, t) ?? w); } public async Task Handle(DeleteWarehouse q, CancellationToken t) { var w = await repository.GetById(q.Id, true, t) ?? throw new EntityNotFoundException("Warehouse not found."); w.IsDeleted = true; w.IsActive = false; w.IsDefault = false; await repository.Save(t); } public async Task<IReadOnlyCollection<WarehouseDropdownDto>> Handle(WarehouseDropdown q, CancellationToken t) { var (x, _) = await repository.Search(q.Search, true, null, "warehouseName", false, 1, 100, t); return x.Select(w => new WarehouseDropdownDto(w.WarehouseId, w.WarehouseCode, w.WarehouseName)).ToArray(); } public async Task<IReadOnlyCollection<WarehouseTypeDto>> Handle(GetWarehouseTypes q, CancellationToken t) => (await repository.Types(t)).Select(TypeDto).ToArray(); public async Task<WarehouseTypeDto> Handle(CreateWarehouseType q, CancellationToken t) { if (await repository.DuplicateType(q.Input.TypeCode, q.Input.TypeName, null, t)) throw new BusinessRuleException("Duplicate warehouse type."); var x = new WarehouseType { TypeCode = q.Input.TypeCode.Trim().ToUpperInvariant(), TypeName = q.Input.TypeName.Trim(), Description = q.Input.Description, IsActive = q.Input.IsActive }; repository.Add(x); await repository.Save(t); return TypeDto(x); } public async Task<WarehouseTypeDto> Handle(UpdateWarehouseType q, CancellationToken t) { var x = await repository.GetTypeById(q.Id, true, t) ?? throw new EntityNotFoundException("Warehouse type not found."); if (await repository.DuplicateType(q.Input.TypeCode, q.Input.TypeName, q.Id, t)) throw new BusinessRuleException("Duplicate warehouse type."); x.TypeCode = q.Input.TypeCode.Trim().ToUpperInvariant(); x.TypeName = q.Input.TypeName.Trim(); x.Description = q.Input.Description; x.IsActive = q.Input.IsActive; await repository.Save(t); return TypeDto(x); } public async Task Handle(DeleteWarehouseType q, CancellationToken t) { var x = await repository.GetTypeById(q.Id, true, t) ?? throw new EntityNotFoundException("Warehouse type not found."); repository.Remove(x); await repository.Save(t); } public async Task<byte[]> Handle(ExportWarehouses q, CancellationToken t) { var (x, _) = await repository.Search(null, null, null, "warehouseName", false, 1, 10000, t); return spreadsheet.Export(x); } public Task<byte[]> Handle(WarehouseTemplate q, CancellationToken t) => Task.FromResult(spreadsheet.Template()); public async Task<ImportResult> Handle(ImportWarehouses q, CancellationToken t) { var errors = new List<string>(); var imported = 0; var types = await repository.Types(t); foreach (var row in spreadsheet.Read(q.Data)) { var type = types.FirstOrDefault(x => x.TypeCode.Equals(row.TypeCode, StringComparison.OrdinalIgnoreCase)); if (type is null) { errors.Add($"Row {row.Row}: warehouse type '{row.TypeCode}' not found."); continue; } if (await repository.Duplicate(row.Code, row.Name, null, t)) { errors.Add($"Row {row.Row}: duplicate warehouse."); continue; } repository.Add(new Warehouse { WarehouseCode = row.Code.ToUpperInvariant(), WarehouseName = row.Name, WarehouseTypeId = type.WarehouseTypeId, ManagerName = row.ManagerName, Email = row.Email, Phone = row.Phone, Mobile = row.Mobile, Capacity = row.Capacity, IsDefault = row.IsDefault, IsActive = row.IsActive, CreatedBy = user.Username }); imported++; } if (imported > 0) await repository.Save(t); return new(imported, errors); } private static WarehouseTypeDto TypeDto(WarehouseType x) => new(x.WarehouseTypeId, x.TypeCode, x.TypeName, x.Description, x.IsActive); }
